                media_total = soma_media / num_alunos;

                cout << "A média do conjunto de todos os alunos é: " << media_total << endl;
                break;
            }

            case ‘H’: {
                string nome;
                cout << "Insira o nome do aluno a ser removido: ";
                cin >> nome;
                bool removed = false;

                for (int i = 0; i < num_alunos; i++) {
                    if (alunos[i].getNome() == nome) {
                        for (int j = i; j < num_alunos - 1; j++) {
                            alunos[j] = alunos[j + 1];
                        }

                        num_alunos–;

                        removed = true;
                        cout << “Aluno removido com sucesso!” << endl;
                        break;
                    }
                }

                if (!removed) {
                    cout << “Aluno não encontrado.” << endl;
                }
                break;
            }

            case ‘S’:
                break;

            default:
                cout << “Opção inválida.” << endl;
        }
    } while (opcao != ‘S’);

    return 0;
}

